import{_ as e,o as t,c as n,ae as s}from"./chunks/framework.Dn6zxbF8.js";const p=JSON.parse(`{"title":"Building stanctl, a self-hosted Instana CLI in Go","description":"How I used Go's CLI patterns and SSH/API automation to turn a manual Instana deployment into one repeatable command.","frontmatter":{"title":"Building stanctl, a self-hosted Instana CLI in Go","description":"How I used Go's CLI patterns and SSH/API automation to turn a manual Instana deployment into one repeatable command.","author":"vinaykumar","date":"2026-09-28T00:00:00.000Z","tags":["go","cli","instana","kubernetes"],"outline":"deep","editLink":false},"headers":[],"relativePath":"blog/building-stanctl-cli.md","filePath":"blog/building-stanctl-cli.md"}`),l={name:"blog/building-stanctl-cli.md"};function i(o,a,r,d,c,u){return t(),n("div",null,[...a[0]||(a[0]=[s('<h1 id="building-stanctl-a-self-hosted-instana-cli-in-go" tabindex="-1">Building stanctl, a self-hosted Instana CLI in Go <a class="header-anchor" href="#building-stanctl-a-self-hosted-instana-cli-in-go" aria-label="Permalink to &quot;Building stanctl, a self-hosted Instana CLI in Go&quot;">​</a></h1><p>Deploying Instana self-hosted involves many moving parts: provisioning IBM Cloud VPCs, standing up Kubernetes clusters, and installing the Instana agents. I built <code>stanctl</code> to encode those steps as a single Go CLI so a new environment is one command instead of a runbook.</p><h2 id="why-a-cli" tabindex="-1">Why a CLI? <a class="header-anchor" href="#why-a-cli" aria-label="Permalink to &quot;Why a CLI?&quot;">​</a></h2><p>A CLI gives us a small surface area that is easy to run from a laptop, a CI pipeline, or a jump host. In Go that means:</p><ul><li><code>cobra</code> (or plain flag parsing) for the command tree,</li><li>context-aware calls for timeouts and cancellation,</li><li>structured logging so automation output is greppable.</li></ul><p>The result is a tool that returns a clear error and exit code instead of leaving a half-provisioned cluster.</p><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vpc -&gt; kubernetes cluster -&gt; instana agent -&gt; verify</span></span></code></pre></div><p>Each stage is a separate subcommand so it can be re-run independently. Re-running a stage is safe because every stage checks the current state before it changes anything.</p><h2 id="what-i-learned" tabindex="-1">What I learned <a class="header-anchor" href="#what-i-learned" aria-label="Permalink to &quot;What I learned&quot;">​</a></h2><ul><li>Keep each command small and composable.</li><li>Use the Kubernetes client-go library for cluster work instead of shelling out to <code>kubectl</code>.</li><li>Surface Helm values as flags so upgrades are controlled from the CLI.</li></ul><p>This post is a living note — I&#39;ll expand it as the CLI grows.</p>',12)])])}const g=e(l,[["render",i]]);export{p as __pageData,g as default};
